use crate::context_deserialize;
use crate::test_utils::TestRandom;
use crate::{ConsolidationRequest, DepositRequest, EthSpec, ForkName, Hash256, WithdrawalRequest};
use alloy_primitives::Bytes;
use derivative::Derivative;
use ethereum_hashing::{DynamicContext, Sha256Context};
use serde::{Deserialize, Serialize};
use ssz::Encode;
use ssz_derive::{Decode, Encode};
use ssz_types::VariableList;
use test_random_derive::TestRandom;
use tree_hash_derive::TreeHash;

pub type DepositRequests<E> =
    VariableList<DepositRequest, <E as EthSpec>::MaxDepositRequestsPerPayload>;
pub type WithdrawalRequests<E> =
    VariableList<WithdrawalRequest, <E as EthSpec>::MaxWithdrawalRequestsPerPayload>;
pub type ConsolidationRequests<E> =
    VariableList<ConsolidationRequest, <E as EthSpec>::MaxConsolidationRequestsPerPayload>;

#[cfg_attr(
    feature = "arbitrary",
    derive(arbitrary::Arbitrary),
    arbitrary(bound = "E: EthSpec")
)]
#[derive(
    Debug, Derivative, Default, Clone, Serialize, Deserialize, Encode, Decode, TreeHash, TestRandom,
)]
#[serde(bound = "E: EthSpec")]
#[derivative(PartialEq, Eq, Hash(bound = "E: EthSpec"))]
#[context_deserialize(ForkName)]
pub struct ExecutionRequests<E: EthSpec> {
    pub deposits: DepositRequests<E>,
    pub withdrawals: WithdrawalRequests<E>,
    pub consolidations: ConsolidationRequests<E>,
}

impl<E: EthSpec> ExecutionRequests<E> {
    /// Returns the encoding according to EIP-7685 to send
    /// to the execution layer over the engine api.
    pub fn get_execution_requests_list(&self) -> Vec<Bytes> {
        let mut requests_list = Vec::new();
        if !self.deposits.is_empty() {
            requests_list.push(Bytes::from_iter(
                [RequestType::Deposit.to_u8()]
                    .into_iter()
                    .chain(self.deposits.as_ssz_bytes()),
            ));
        }
        if !self.withdrawals.is_empty() {
            requests_list.push(Bytes::from_iter(
                [RequestType::Withdrawal.to_u8()]
                    .into_iter()
                    .chain(self.withdrawals.as_ssz_bytes()),
            ));
        }
        if !self.consolidations.is_empty() {
            requests_list.push(Bytes::from_iter(
                [RequestType::Consolidation.to_u8()]
                    .into_iter()
                    .chain(self.consolidations.as_ssz_bytes()),
            ));
        }
        requests_list
    }

    /// Generate the execution layer `requests_hash` based on EIP-7685.
    ///
    /// `sha256(sha256(requests_0) ++ sha256(requests_1) ++ ...)`
    pub fn requests_hash(&self) -> Hash256 {
        let mut hasher = DynamicContext::new();

        for request in self.get_execution_requests_list().iter() {
            let mut request_hasher = DynamicContext::new();
            request_hasher.update(request);
            let request_hash = request_hasher.finalize();

            hasher.update(&request_hash);
        }

        hasher.finalize().into()
    }
}

/// The prefix types for `ExecutionRequest` objects.
#[derive(Debug, Copy, Clone)]
pub enum RequestType {
    Deposit,
    Withdrawal,
    Consolidation,
}

impl RequestType {
    pub fn from_u8(prefix: u8) -> Option<Self> {
        match prefix {
            0 => Some(Self::Deposit),
            1 => Some(Self::Withdrawal),
            2 => Some(Self::Consolidation),
            _ => None,
        }
    }
    pub fn to_u8(&self) -> u8 {
        match self {
            Self::Deposit => 0,
            Self::Withdrawal => 1,
            Self::Consolidation => 2,
        }
    }
}

#[cfg(test)]
mod tests {
    use crate::MainnetEthSpec;

    use super::*;

    ssz_and_tree_hash_tests!(ExecutionRequests<MainnetEthSpec>);
}

use crate::{
    json_structures::{EncodableJsonWithdrawal, JsonWithdrawal},
    keccak::{KeccakHasher, keccak256},
};
use alloy_rlp::Encodable;
use keccak_hash::KECCAK_EMPTY_LIST_RLP;
use triehash::ordered_trie_root;
use types::{
    EncodableExecutionBlockHeader, EthSpec, ExecutionBlockHash, ExecutionBlockHeader,
    ExecutionPayloadRef, ExecutionRequests, Hash256,
};

/// Calculate the block hash of an execution block.
///
/// Return `(block_hash, transactions_root)`, where `transactions_root` is the root of the RLP
/// transactions.
pub fn calculate_execution_block_hash<E: EthSpec>(
    payload: ExecutionPayloadRef<E>,
    parent_beacon_block_root: Option<Hash256>,
    execution_requests: Option<&ExecutionRequests<E>>,
) -> (ExecutionBlockHash, Hash256) {
    // Calculate the transactions root.
    // We're currently using a deprecated Parity library for this. We should move to a
    // better alternative when one appears, possibly following Reth.
    let rlp_transactions_root = ordered_trie_root::<KeccakHasher, _>(
        payload.transactions().iter().map(|txn_bytes| &**txn_bytes),
    );

    // Calculate withdrawals root (post-Capella).
    let rlp_withdrawals_root = if let Ok(withdrawals) = payload.withdrawals() {
        Some(ordered_trie_root::<KeccakHasher, _>(
            withdrawals
                .iter()
                .map(|withdrawal| rlp_encode_withdrawal(&JsonWithdrawal::from(withdrawal.clone()))),
        ))
    } else {
        None
    };

    let rlp_blob_gas_used = payload.blob_gas_used().ok();
    let rlp_excess_blob_gas = payload.excess_blob_gas().ok();
    let requests_root = execution_requests.map(|requests| requests.requests_hash());

    // Construct the block header.
    let exec_block_header = ExecutionBlockHeader::from_payload(
        payload,
        KECCAK_EMPTY_LIST_RLP.as_fixed_bytes().into(),
        rlp_transactions_root,
        rlp_withdrawals_root,
        rlp_blob_gas_used,
        rlp_excess_blob_gas,
        parent_beacon_block_root,
        requests_root,
    );

    // Hash the RLP encoding of the block header.
    let rlp_block_header = rlp_encode_block_header(&exec_block_header);
    (
        ExecutionBlockHash::from_root(keccak256(&rlp_block_header)),
        rlp_transactions_root,
    )
}

/// RLP encode a withdrawal.
pub fn rlp_encode_withdrawal(withdrawal: &JsonWithdrawal) -> Vec<u8> {
    let mut out: Vec<u8> = vec![];
    EncodableJsonWithdrawal::from(withdrawal).encode(&mut out);
    out
}

/// RLP encode an execution block header.
pub fn rlp_encode_block_header(header: &ExecutionBlockHeader) -> Vec<u8> {
    let mut out: Vec<u8> = vec![];
    EncodableExecutionBlockHeader::from(header).encode(&mut out);
    out
}

