    tx: &types::Transaction<N>,
) -> Result<TxEnvelope, Error> {
    let tx_bytes = Vec::from(tx.clone());
    TxEnvelope::decode(&mut tx_bytes.as_slice())
        .map_err(|e| Error::DecodingTransaction(e.to_string()))
}

